def transform(grid):
    h, w = len(grid), len(grid[0])

    # In the horizontal-band example, copy the last colored band into the blank row.
    nonempty_rows = [r for r in range(h) if any(grid[r])]
    if nonempty_rows and all(
        len(set(grid[r])) == 1 for r in nonempty_rows
    ):
        out = [row[:] for row in grid]
        for r in range(h):
            if not any(grid[r]):
                out[r] = grid[nonempty_rows[-1]][:]
        return out

    marks = [
        (r, c, grid[r][c])
        for r in range(h) for c in range(w)
        if grid[r][c] != 0
    ]

    # The diagonal lines indicate a repeating color pattern. Try both diagonal
    # orientations and periods, looking for a consistent color per residue.
    candidates = []
    for sign in (1, -1):
        for period in range(2, max(h, w) + 1):
            pattern = {}
            valid = True
            for r, c, color in marks:
                residue = (c + sign * r) % period
                if residue in pattern and pattern[residue] != color:
                    valid = False
                    break
                pattern[residue] = color
            if valid and len(pattern) == period:
                candidates.append((period, sign, pattern))

    if candidates:
        period, sign, pattern = min(candidates, key=lambda x: x[0])
        return [
            [pattern[(c + sign * r) % period] for c in range(w)]
            for r in range(h)
        ]

    return [row[:] for row in grid]
